#include "rsr_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

#if RSR_DISARM_ENA == 1
  #if !defined RSR_DISARM_SET || !defined RSR_DISARM_CLR
    #error !!!RSR_DISARM_SET/CLR must be defined in DB3 core contract mapping!!!
  #endif									
#endif 

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void rsr_disarm (void * arg)
{
  #if RSR_DISARM_ENA == 1
	rsr_out_action (RSR_DISARM_OUT, 0, rsr_opt.unlock.dur, RSR_OUT_PAUSE, 1) ;
  #endif
}

//--------------------------------------------------------------------------//

void rsr_disarm_timeout (void * arg)
{
  #if RSR_DISARM_ENA == 1	
	  switch (rsr_out_ctl(RSR_DISARM_OUT))
      {
	  	  case RSR_OUT_STATE_SET : RSR_DISARM_SET ; break ;
        case RSR_OUT_STATE_CLR : RSR_DISARM_CLR ; break ;
	  	  default: break ;
	    }
  #endif 
}

